mapper.select:
SELECT id::text AS model_id,  AS stored_draft, time_pricing_rule_id AS rule_id
FROM nw_platform_models
WHERE draft->>'provider_id' IS NOT DISTINCT FROM #{provider,jdbcType=VARCHAR}
  AND draft->>'model_id' IS NOT DISTINCT FROM #{model,jdbcType=VARCHAR}
  AND draft->>'kind' NOT IN ('IMAGE_GENERATION','VIDEO_GENERATION','SPEECH_RECOGNITION','SPEECH_SYNTHESIS')
ORDER BY id
